fn split_and_append(list: &Vec<i32>, n: usize) -> Vec<i32> {
    let len = list.len();
    // Pre-allocate a new Vec with capacity equal to the length of the input
    let mut new_list = Vec::with_capacity(len);

    // Append elements from index n to end
    new_list.extend_from_slice(&list[n..]);
    // Append elements from start to index n (exclusive)
    new_list.extend_from_slice(&list[..n]);

    new_list
}